-- Scraper for Bouygues Telecom's customer account (www.bouyguestelecom.fr/mon-compte):
-- downloads mobile/internet invoices.
--
-- **Why `fyde.browser` instead of `fyde.http`.** `/mon-compte` is a client-rendered SPA: login
-- happens inside an OAuth2 (PKCE) iframe (`#bytelid_a360_login`, pointing at
-- oauth2.bouyguestelecom.fr/authorize) whose `code_challenge`/`state`/`nonce` are generated by
-- the page's own JS, and the resulting access token only ever lives in the SPA's sessionStorage
-- (`a360-access_token`). There's no way to
-- replay that with a plain HTTP client, so this script drives a real webview instead.
--
-- **Confirmed via live, logged-out runs of this script** (no HAR was available):
--   1. `BILLS_URL` (like the rest of /mon-compte) embeds `#bytelid_a360_login` while logged
--      out, an iframe whose `src` is the CAS-backed
--      login page. Opening that `src` top-level (as the original implementation also does) renders both a
--      React form (`#picasso-username`/`#picasso-password`) and the underlying CAS form `#fm1`
--      with plain hidden `username`/`password` inputs plus its own `execution`/`_eventId`
--      fields and a hidden `button[name=submit]`.
--   2. This script fills `#fm1`'s hidden fields and clicks its own submit button directly,
--      bypassing the React form: `fyde.browser:fill` sets `.value` + dispatches `input`, which
--      React's controlled-input value tracker ignores, so filling the visible React inputs
--      would most likely submit empty state.
--
--   3. A fresh login always asks for a one-time code (SMS/e-mail channel choice, then the code
--      itself, then a "Continuer" screen) - see `confirm_with_code`/`login`. A run that reuses
--      a saved session (the sdk restores the webview's cookies when the previous run
--      succeeded) skips all of it.
--   4. Invoices (`BILLS_URL`) are listed in two tables and downloaded by clicking each row's
--      "Télécharger" link, which `window.open`s a `blob:` PDF that the webview turns into a
--      native download - see `parse_invoices`/`save_invoice`. One very old invoice (2021) comes
--      back as a 2-byte body and is skipped with a warning.

local M = {}

local MON_COMPTE_URL = "https://www.bouyguestelecom.fr/mon-compte"
local BILLS_URL = MON_COMPTE_URL .. "/mes-factures"

local LOGIN_IFRAME = "#bytelid_a360_login"
local CAS_FORM = "#fm1"

-- Confirmed with a deliberately wrong login (see `login`).
local BAD_CREDENTIALS = { "identifiant ou votre mot de passe est incorrect", "mot de passe est incorrect" }

-- Nothing here sleeps for a fixed delay: every wait polls the page every `POLL_MS` for a
-- concrete marker of the state it's waiting for, giving up after `PAGE_TIMEOUT_MS`.
local POLL_MS = 500
local PAGE_TIMEOUT_MS = 30000

-- Confirmed by polling both states: logged in, `BILLS_URL`'s "Mes factures" tab renders ~1.5s
-- after opening and the invoice tables ~0.5s later, and the login iframe never does; logged
-- out, the login iframe renders (~1.5s) and the tab never does.
local INVOICES_TAB = 'a[data-route="invoicesV4"]'

-- luacheck: push ignore 211
-- ---------------------------------------------------------------------------------------------
-- Shared block (identical in every scraper - see README.md).
--
-- Login error contract: a rejected username/password always fails the run with exactly
-- `INVALID_CREDENTIALS`, and a rejected, expired or unanswered OTP/MFA step with exactly
-- `MFA_FAILED` (both raised with `error(code, 0)`, so the message carries no position prefix).
-- Any other failure is a free-form error message.
--
-- Log markers (grepped by tests/login_smoke.sh): `LOGIN_PAGE_FOUND` once the login form has
-- been seen, `ALREADY_LOGGED_IN` when a restored session made the login step unnecessary.
-- ---------------------------------------------------------------------------------------------
local INVALID_CREDENTIALS = "INVALID_CREDENTIALS"
local MFA_FAILED = "MFA_FAILED"

local function fail(code, detail)
  if detail then
    fyde.log.warn(code .. ": " .. detail)
  end
  error(code, 0)
end

local function contains(haystack, needle)
  return (haystack or ""):lower():find(needle:lower(), 1, true) ~= nil
end

local function contains_any(haystack, needles)
  for _, needle in ipairs(needles) do
    if contains(haystack, needle) then
      return true
    end
  end
  return false
end

local function trim(s)
  return ((s or ""):gsub("^%s+", ""):gsub("%s+$", ""))
end

local function sanitize(name)
  name = trim((name or ""):gsub("%s+", " "))
  name = name:gsub('[<>:"/\\|%?%*]', "_"):gsub("%c", "")
  if name == "" then
    name = "document"
  end
  return name
end

-- A `kind:value` subject for fyde.save_document's `subjects`: who or what the document concerns
-- when the account covers several (`person`, `line`, `account`, `contract`, `place`, `vehicle`
-- or `trip`). The value is lowercased with runs of spaces/punctuation turned into "-"; nil for a
-- blank value, which a `subjects` list simply skips.
local function subject(kind, value)
  local slug = trim(value or ""):lower():gsub("[%s%p]+", "-"):gsub("^%-+", ""):gsub("%-+$", "")
  if slug == "" then
    return nil
  end
  return kind .. ":" .. slug
end

-- Masks all but the last `keep` characters of an identifier (phone number, IBAN, contract
-- number...), enough to tell them apart without spelling them out in a subject.
local function mask(value, keep)
  value = (value or ""):gsub("%s", "")
  if #value <= keep then
    return value
  end
  return string.rep("x", #value - keep) .. value:sub(-keep)
end

-- Asks the user for a one-time code through fyde.input.ask; an unanswered/empty prompt (or no
-- input handler at all, e.g. an unattended run) is an MFA failure.
local function ask_code(question)
  local ok, code = pcall(fyde.input.ask, question)
  if not ok or type(code) ~= "string" or trim(code) == "" then
    fail(MFA_FAILED, "no one-time code was provided")
  end
  return (code:gsub("%s", ""))
end

-- `wait_for` only waits for a selector to appear, so sleeping means waiting on one that never
-- exists.
local function sleep(ms)
  pcall(function()
    fyde.browser:wait_for("#__fyde_scraper_sleep__", ms)
  end)
end

local function page_html()
  local ok, html = pcall(function()
    return fyde.browser:html()
  end)
  return ok and html or ""
end

local function present(selector)
  return #fyde.html.select(page_html(), selector) > 0
end

local function page_text()
  local body = fyde.html.select(page_html(), "body")[1]
  return body and body.text or ""
end

-- Polls the current page until one of `states` matches and returns its name (or nil after
-- `timeout_ms`). Each state is `{ name, selector = css }` or `{ name, text = { needles } }`.
-- Polling in short chunks also survives `fyde.browser:open` not waiting for navigation (a
-- `wait_for` issued against the previous page just times out and gets retried).
local function wait_state(states, timeout_ms)
  local waited = 0
  repeat
    local html = page_html()
    local text
    for _, state in ipairs(states) do
      if state.selector and #fyde.html.select(html, state.selector) > 0 then
        return state[1]
      end
      if state.text then
        if not text then
          local body = fyde.html.select(html, "body")[1]
          text = body and body.text or ""
        end
        if contains_any(text, state.text) then
          return state[1]
        end
      end
    end
    sleep(1000)
    waited = waited + 1000
  until waited >= (timeout_ms or 30000)
  return nil
end

local function open_and_wait(url, states, timeout_ms)
  fyde.browser:open(url)
  sleep(1500)
  return wait_state(states, timeout_ms)
end

-- Fills the first present selector of each candidate list.
local function fill_first(selectors, value)
  for _, selector in ipairs(selectors) do
    if present(selector) then
      fyde.browser:fill(selector, value)
      return selector
    end
  end
  error("none of " .. table.concat(selectors, ", ") .. " is on the page")
end

local function click_first(selectors)
  for _, selector in ipairs(selectors) do
    if present(selector) then
      fyde.browser:click(selector)
      return selector
    end
  end
  error("none of " .. table.concat(selectors, ", ") .. " is on the page")
end

-- Clicks `selector` (a download link/button) and saves what the browser downloads.
local function browser_save(selector, filename, fields)
  local ok, bytes = pcall(function()
    return fyde.browser:download(selector, 60000)
  end)
  if ok and type(bytes) == "string" and bytes:sub(1, 4) == "%PDF" then
    fyde.save_document(sanitize(filename), bytes, fields)
    return true
  end
  fyde.log.warn("could not download " .. filename .. ": " .. tostring(ok and "not a PDF" or bytes))
  return false
end
-- luacheck: pop


-- Polls the current page every POLL_MS until `check(html)` returns something truthy, and
-- returns that (or nil once `timeout_ms` is up). `fyde.browser:open` doesn't wait for the
-- navigation it starts, so the first polls after one may still see the previous page - every
-- `check` below looks for a marker that page can't have.
local function poll(check, timeout_ms)
  local waited = 0
  while true do
    local result = check(page_html())
    if result then
      return result
    end
    if waited >= timeout_ms then
      return nil
    end
    sleep(POLL_MS)
    waited = waited + POLL_MS
  end
end

local function has(html, selector)
  return fyde.html.select(html, selector)[1] ~= nil
end

-- Opens `BILLS_URL` and waits until it's clear whether the session is logged in (see
-- INVOICES_TAB). Returns that, plus the page's HTML.
local function open_bills()
  fyde.browser:open(BILLS_URL)
  local state = poll(function(html)
    if has(html, INVOICES_TAB) then
      return "logged_in"
    elseif has(html, LOGIN_IFRAME) then
      return "logged_out"
    end
  end, PAGE_TIMEOUT_MS)
  if not state then
    error("timed out waiting for " .. BILLS_URL .. " to show either the invoices or the login iframe")
  end
  return state == "logged_in", page_html()
end

-- CAS bookkeeping fields every step's hidden form carries, never the one to fill in.
local CAS_META_FIELDS = { conversationId = true, geolocation = true, _eventId = true, execution = true }

-- Every CAS step seen so far (login, OTP channel choice) renders a React UI on top of a plain,
-- hidden `<form method="post">` carrying `execution` plus exactly one real field and a hidden
-- submit button. Returns that form's id and its one real field's name, or nil.
local function find_cas_form(html)
  for _, form in ipairs(fyde.html.select(html, 'form[method="post"]')) do
    local id = form.attrs.id
    if id and form.html:find('name="execution"', 1, true) then
      for _, input in ipairs(fyde.html.select(form.html, "input[name]")) do
        if not CAS_META_FIELDS[input.attrs.name] then
          return id, input.attrs.name
        end
      end
    end
  end
  return nil
end

local function error_messages(html, selector)
  local messages = {}
  for _, e in ipairs(fyde.html.select(html, selector)) do
    local text = trim(e.text:gsub("%s+", " "))
    if text ~= "" then
      messages[#messages + 1] = text
    end
  end
  return table.concat(messages, " / ")
end

local function log_cas_form(html)
  local id, field = find_cas_form(html)
  fyde.log.info("CAS form on this page: id=" .. tostring(id) .. " field=" .. tostring(field))
  for _, e in ipairs(fyde.html.select(html, "input, button")) do
    local attrs = {}
    for k, v in pairs(e.attrs) do
      if #v < 80 then
        attrs[#attrs + 1] = k .. "=" .. v
      end
    end
    fyde.log.info("  " .. table.concat(attrs, " ") .. " | " .. (e.text:gsub("%s+", " ")))
  end
end

local function execution_of(html)
  local input = fyde.html.select(html, 'input[name="execution"]')[1]
  return input and input.attrs.value
end

-- Clicks a CAS submit control and waits for CAS's answer. Every CAS page carries a fresh
-- `execution` token (confirmed: it changes even when CAS re-renders the same form with an
-- error), so CAS has answered once the page's token differs from the one before the click -
-- or, for the step that leaves CAS for the OAuth callback, once there's no token at all on two
-- polls in a row (one could just be a page caught mid-parse).
local function cas_click(selector)
  local before = execution_of(page_html())
  fyde.browser:click(selector)
  local gone = 0
  local html = poll(function(html)
    local now = execution_of(html)
    if now and now ~= "" and now ~= before then
      return html
    end
    gone = now and 0 or gone + 1
    if gone >= 2 then
      return html
    end
  end, PAGE_TIMEOUT_MS)
  if not html then
    error("timed out waiting for Bouygues Telecom's login server to answer")
  end
  return html
end

-- Fills the page's hidden CAS form's one real field with `value` and submits it.
local function submit_cas_form(html, value)
  local id, field = find_cas_form(html)
  if not id then
    log_cas_form(html)
    error("couldn't find the hidden CAS form to submit on this page")
  end
  fyde.browser:fill("#" .. id .. ' input[name="' .. field .. '"]', value)
  return cas_click("#" .. id .. ' [type="submit"]')
end

-- Confirmed on a real login: after the password, CAS asks which channel to send a one-time
-- code to - `.radio-tile`s whose `input[name=choice]` values are the masked phone/e-mail - and
-- expects the chosen masked value in `#contactSelectionForm`'s hidden `maskedValue` field.
local function confirm_with_code(html)
  local choices = fyde.html.select(html, 'input[name="choice"]')
  local choice = choices[1]
  for _, c in ipairs(choices) do
    if c.attrs.checked then
      choice = c
      break
    end
  end
  if not choice then
    log_cas_form(html)
    error("Bouygues Telecom is asking for a confirmation code, but no delivery channel was found")
  end

  fyde.progress.step("Requesting a confirmation code")
  html = submit_cas_form(html, choice.attrs.value)

  -- Confirmed on a real login: the code page is `#fm1` again with a hidden `token` field
  -- (`#codeOtp`); a rejected code re-renders that same page, so ask again rather than failing
  -- the whole login (and spending another SMS) over a typo.
  local question = "Bouygues Telecom confirmation code sent to " .. choice.attrs.value .. ":"
  for _ = 1, 3 do
    local code = ask_code(question)
    fyde.progress.step("Submitting the confirmation code")
    html = submit_cas_form(html, code)
    if not fyde.html.select(html, "#codeOtp")[1] then
      return html
    end
    local reason = error_messages(html, ".is-error, [role=alert]")
    if reason == "" then
      reason = "code rejected"
    end
    fyde.log.warn("confirmation code rejected: " .. reason)
    question = "Code rejected (" .. reason .. "), enter it again:"
  end
  fail(MFA_FAILED, "confirmation code rejected 3 times")
end

local function login(params, html)
  local frame = fyde.html.select(html, LOGIN_IFRAME)[1]
  if not frame or not frame.attrs.src then
    error("neither logged in nor showing the login iframe (" .. LOGIN_IFRAME .. ") on " .. BILLS_URL)
  end

  fyde.progress.step("Logging in")
  fyde.browser:open(frame.attrs.src)
  if not poll(function(page)
    return has(page, CAS_FORM)
  end, PAGE_TIMEOUT_MS) then
    error("timed out waiting for the login form (" .. CAS_FORM .. ")")
  end
  fyde.log.info("LOGIN_PAGE_FOUND")
  fyde.browser:fill(CAS_FORM .. ' input[name="username"]', params.username)
  fyde.browser:fill(CAS_FORM .. ' input[name="password"]', params.password)

  local after = cas_click(CAS_FORM .. ' button[name="submit"]')
  if after:find('id="fm1"', 1, true) then
    -- Confirmed with a deliberately wrong login: the CAS form re-renders with
    -- "Votre identifiant ou votre mot de passe est incorrect" in `p.help.is-error`. Any other
    -- (or no) message isn't treated as a credentials rejection.
    local message = error_messages(after, "p.help.is-error")
    if contains_any(message, BAD_CREDENTIALS) then
      fail(INVALID_CREDENTIALS, message)
    end
    error(
      "still on the login form after submitting credentials: "
        .. (message ~= "" and message or "no error message shown")
    )
  end
  if fyde.html.select(after, ".radio-tile")[1] then
    after = confirm_with_code(after)
  end
  -- Confirmed on a real login: an accepted code lands on a confirmation screen ("Continuer")
  -- whose hidden `#proceed` submit (`_eventId_proceed`) finishes the CAS flow and redirects
  -- back to the OAuth callback. Until it's clicked, /mon-compte still shows the login iframe.
  if has(after, "#proceed") then
    cas_click("#proceed")
  end

  local logged_in = open_bills()
  if not logged_in then
    log_cas_form(after)
    error("login submitted, but " .. BILLS_URL .. " still shows the login iframe")
  end
end

-- Confirmed on the real invoices page: two invoice tables, "Mes dernières factures" (the
-- latest month, in the `has-background-tertiary` section) and "Mes factures" (everything
-- older, in the `has-background-white` section, ending with a `tr.is-expansion` "Afficher les
-- 10 factures suivantes" row). Each has one row per invoice (6 cells: date, type, line number,
-- amount, status, actions) interleaved with month-header rows (a single `th`).
local INVOICE_TABLES = {
  "section.has-background-tertiary table.table tbody",
  "section.has-background-white table.table tbody",
}
local LOAD_MORE = "table.table tbody tr.is-expansion a.link"
local MAX_LOAD_MORE = 20

local function load_all_invoices()
  -- Both tables have rendered once the row count stops changing between two polls.
  local rows = -1
  local html = poll(function(page)
    local count = #fyde.html.select(page, "table.table tbody tr")
    local settled = count > 0 and count == rows
    rows = count
    return settled and page
  end, PAGE_TIMEOUT_MS)
  if not html then
    error("no invoice table showed up on " .. BILLS_URL)
  end
  for _ = 1, MAX_LOAD_MORE do
    if not fyde.html.select(html, LOAD_MORE)[1] then
      break
    end
    local before = #fyde.html.select(html, "table.table tbody tr")
    fyde.browser:click(LOAD_MORE)
    local more = poll(function(page)
      return #fyde.html.select(page, "table.table tbody tr") > before and page
    end, PAGE_TIMEOUT_MS)
    if not more then
      fyde.log.warn("clicking \"load more\" didn't add any invoice, stopping there")
      break
    end
    html = more
  end
  return html
end

local function text_of(html, selector)
  local e = fyde.html.select(html, selector)[1]
  return e and trim(e.text:gsub("%s+", " ")) or ""
end

local function parse_invoices(html)
  local invoices = {}
  for _, tbody in ipairs(INVOICE_TABLES) do
    for index, row in ipairs(fyde.html.select(html, tbody .. " > tr")) do
      -- A bare `<tr>` fragment loses its `td`s when parsed on its own (the HTML parser drops
      -- table cells outside a table), hence the wrapping.
      local cells = fyde.html.select("<table><tbody>" .. row.html .. "</tbody></table>", "td")
      if #cells == 6 then
        local day, month, year = cells[1].text:match("(%d%d)/(%d%d)/(%d%d%d%d)")
        local euros = text_of(cells[4].html, ".price .main")
        local cents = text_of(cells[4].html, ".price .cents"):match("%d+")
        invoices[#invoices + 1] = {
          -- `tbody`'s children are all `tr`s, so the row's position in the select is its
          -- `:nth-child` index - the only way to point fyde.browser:download at one row's link.
          selector = tbody .. " > tr:nth-child(" .. index .. ") td:last-child a.link",
          date = day and (year .. "-" .. month .. "-" .. day),
          kind = text_of(cells[2].html, "p"),
          line = text_of(cells[3].html, "p"),
          amount = euros ~= "" and (euros .. "," .. (cents or "00") .. " €") or nil,
        }
      end
    end
  end
  return invoices
end

local function save_invoice(invoice)
  local ok, body = pcall(function()
    return fyde.browser:download(invoice.selector, 60000)
  end)
  if not ok then
    fyde.log.warn("failed to download the " .. tostring(invoice.date) .. " invoice: " .. tostring(body))
    return false
  end
  if body:sub(1, 5) ~= "%PDF-" then
    fyde.log.warn("the " .. tostring(invoice.date) .. " invoice isn't a PDF (" .. #body .. " bytes), skipping")
    return false
  end

  local line = invoice.line:gsub("%s", "")
  local title = invoice.kind ~= "" and invoice.kind or "Facture"
  -- Mobile numbers start with 06/07; any other line on a Bouygues invoice is a Bbox line, filed
  -- under housing like every other internet box. Some invoices (e.g. "Facture d'achat", an
  -- equipment purchase) have no line at all, so they get no subcategory rather than a guessed one.
  local category, subcategory = "telecom", nil
  if line ~= "" then
    if line:match("^0[67]") then
      subcategory = "mobile"
    else
      category, subcategory = "housing", "internet"
    end
  end
  local name = "Bouygues Telecom - " .. title
  if invoice.line ~= "" then
    name = name .. " " .. invoice.line
  end
  name = name .. " - " .. (invoice.date or "date inconnue")
  if invoice.amount then
    name = name .. " - " .. invoice.amount
  end
  local slug = line ~= "" and line or title:gsub("%s+", "-")
  fyde.save_document(sanitize((invoice.date or "facture") .. "_bouyguestelecom_" .. slug) .. ".pdf", body, {
    name = name,
    type = "invoice",
    category = category,
    subcategory = subcategory,
    subjects = { subject("line", mask(line, 4)) },
  })
  return true
end

function M.run(params)
  fyde.progress.step("Checking for an existing session")
  local logged_in, html = open_bills()
  if logged_in then
    fyde.log.info("ALREADY_LOGGED_IN")
  else
    login(params, html)
  end

  fyde.progress.step("Listing invoices")
  local invoices = parse_invoices(load_all_invoices())
  if #invoices == 0 then
    error("no invoice found on " .. BILLS_URL)
  end

  fyde.progress.step("Downloading invoices")
  local saved = 0
  for i, invoice in ipairs(invoices) do
    fyde.progress.update(i, #invoices, tostring(invoice.date) .. " " .. invoice.line)
    if save_invoice(invoice) then
      saved = saved + 1
    elseif i == 3 and saved == 0 then
      -- Each failed download waits out its full timeout; don't do that for every invoice.
      error("the first 3 invoices all failed to download, giving up")
    end
  end
  fyde.log.info("saved " .. saved .. "/" .. #invoices .. " invoices")
  if saved == 0 then
    error("none of the " .. #invoices .. " invoices could be downloaded")
  end
end

return M
